"""Share of the total weight per shipment."""
from shipments import load_shipments


def weight_shares(shipments):
    """Return each shipment's share of the total weight, in order."""
    total = sum(x.weight for x in shipments)
    return [x.weight / total for x in shipments]


def stored_shares():
    """Shares for the stored shipments."""
    return weight_shares(load_shipments())


def top_share(shipments):
    """Return the largest share, or 0.0 when there are no shipments."""
    shares = weight_shares(shipments)
    return max(shares) if shares else 0.0


def describe_shipment(shipment):
    """Return a one-line description of a shipment."""
    return "%s: %s" % (shipment.route, shipment.weight)


def group_by_route(shipments):
    """Return a dict from route to the list of shipments with that route."""
    groups = {}
    for x in shipments:
        groups.setdefault(x.route, []).append(x)
    return groups

